import zlib from 'node:zlib';
const samples=[Buffer.alloc(0),Buffer.from('real zlib bytes\0\u00e9\ud83d\ude00'),Buffer.from(Array.from({length:256},(_,i)=>i)),Buffer.from('abcxyz'.repeat(400))];
const vectors=[];
for(let i=0;i<samples.length;i++)for(const [label,options] of [['stored',{level:0}],['fast',{level:1}],['default',{}],['maximum',{level:9}],['fixed',{strategy:zlib.constants.Z_FIXED}]]){
 const bytes=zlib.deflateSync(samples[i],options); vectors.push({name:`${i}-${label}`,input:bytes.toString('hex'),output:samples[i].toString('hex')});
}
const base=zlib.deflateSync(Buffer.from('zlib checksum and framing'));
const bad=[];for(let i=0;i<base.length;i++)bad.push({name:`truncated-${i}`,bytes:base.subarray(0,i)});
for(const pos of [0,1,2,base.length-4,base.length-1]){const b=Buffer.from(base);b[pos]^=1;bad.push({name:`corrupt-${pos}`,bytes:b});}
bad.push({name:'gzip-is-not-zlib',bytes:zlib.gzipSync('actual bytes')},{name:'raw-is-not-zlib',bytes:zlib.deflateRawSync('actual bytes')},{name:'dictionary',bytes:zlib.deflateSync('dictionary bytes dictionary bytes',{dictionary:Buffer.from('dictionary bytes')})});
for(const x of bad){try{x.output=zlib.inflateSync(x.bytes).toString('hex');}catch(e){x.error=e.name;x.code=e.code;}x.input=x.bytes.toString('hex');delete x.bytes;}
const first=zlib.deflateSync('first');const second=zlib.deflateSync('second');
for(const [name,bytes] of [['trailing',Buffer.concat([first,Buffer.from([255,0,1])])],['concatenated',Buffer.concat([first,second])]])vectors.push({name,input:bytes.toString('hex'),output:zlib.inflateSync(bytes).toString('hex')});
const dictionary=bad.find(x=>x.name==='dictionary');const dictionaryShort=[];for(let i=0;i<6;i++){let b=Buffer.from(dictionary.input,'hex').subarray(0,i);try{zlib.inflateSync(b);dictionaryShort.push(null)}catch(e){dictionaryShort.push(e.code)}}
console.log(JSON.stringify({version:process.version,vectors,bad,dictionaryShort,bomb:zlib.deflateSync(Buffer.alloc(2*1024*1024+1,65)).toString('hex')}));
